CREATE TABLE IF NOT EXISTS `watch_history` (`playbackKey` TEXT NOT NULL, `mediaId` TEXT NOT NULL, `tmdbId` INTEGER, `imdbId` TEXT, `title` TEXT NOT NULL, `mediaType` TEXT NOT NULL, `posterUrl` TEXT, `backdropUrl` TEXT, `seasonNumber` INTEGER, `episodeNumber` INTEGER, `episodeTitle` TEXT, `positionMs` INTEGER NOT NULL, `durationMs` INTEGER NOT NULL, `lastStreamUrlHash` TEXT, `updatedAtMs` INTEGER NOT NULL, PRIMARY KEY(`playbackKey`))
CREATE TABLE IF NOT EXISTS `watchlist` (`mediaId` TEXT NOT NULL, `tmdbId` INTEGER, `imdbId` TEXT, `title` TEXT NOT NULL, `mediaType` TEXT NOT NULL, `posterUrl` TEXT, `backdropUrl` TEXT, `releaseYear` TEXT, `rating` REAL, `isFavorite` INTEGER NOT NULL, `addedAtMs` INTEGER NOT NULL, PRIMARY KEY(`mediaId`))
CREATE TABLE IF NOT EXISTS `addons` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `version` TEXT NOT NULL, `description` TEXT, `manifestUrl` TEXT NOT NULL, `baseUrl` TEXT NOT NULL, `resourcesCsv` TEXT NOT NULL, `typesCsv` TEXT NOT NULL, `idPrefixesCsv` TEXT NOT NULL, `isEnabled` INTEGER NOT NULL, `priorityOrder` INTEGER NOT NULL, `lastHealthStatus` TEXT NOT NULL, `updatedAtMs` INTEGER NOT NULL, PRIMARY KEY(`id`))
